public static class ConnectShowroomTrack {
 static void Ref(Object component,string property,Object value){var s=new SerializedObject(component);s.FindProperty(property).objectReferenceValue=value;s.ApplyModifiedPropertiesWithoutUndo();}
 static void Rect(RectTransform r,Vector2 anchor,Vector2 position,Vector2 size){r.anchorMin=r.anchorMax=anchor;r.pivot=anchor;r.anchoredPosition=position;r.sizeDelta=size;}
 public static string Main(){if(EditorApplication.isPlaying)throw new System.Exception("Edit mode required.");const string dir="Assets/Prefabs/TestDrive";if(AssetDatabase.LoadAssetAtPath<TestDriveVehicleCatalog>(dir+"/VehicleCatalog.asset"))throw new System.Exception("Connection catalog already exists.");var track=SceneManager.GetSceneByPath("Assets/Scenes/TestTrackScene.unity");var showroom=SceneManager.GetSceneByPath("Assets/Scenes/ShowcaseScene.unity");if(!track.IsValid()||!showroom.IsValid())throw new System.Exception("Both scenes must be loaded.");var template=track.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<TestDriveMovement>()).Single();var templateBody=template.GetComponent<Rigidbody>();var templateWheel=template.GetComponentsInChildren<WheelCollider>()[0];var manager=showroom.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<VehicleShowcaseManager>()).Single();var source=new SerializedObject(manager);var originals=source.FindProperty("vehiclePrefabs");var returnSound=(AudioClip)source.FindProperty("backSound").objectReferenceValue;
 if(!AssetDatabase.IsValidFolder(dir))AssetDatabase.CreateFolder("Assets/Prefabs","TestDrive");var catalog=ScriptableObject.CreateInstance<TestDriveVehicleCatalog>();catalog.drivingPrefabs=new TestDriveMovement[originals.arraySize];
 for(int i=0;i<originals.arraySize;i++){var original=(Vehicle)originals.GetArrayElementAtIndex(i).objectReferenceValue;var go=(GameObject)PrefabUtility.InstantiatePrefab(original.gameObject,track);go.name=original.name.Replace("_Showcase","_TestDrive");go.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var rb=go.AddComponent<Rigidbody>();rb.mass=templateBody.mass;rb.useGravity=true;rb.constraints=RigidbodyConstraints.None;rb.interpolation=templateBody.interpolation;rb.collisionDetectionMode=templateBody.collisionDetectionMode;rb.linearDamping=templateBody.linearDamping;rb.angularDamping=templateBody.angularDamping;var mesh=go.GetComponent<MeshFilter>().sharedMesh;rb.centerOfMass=i==0?templateBody.centerOfMass:new Vector3(0,Mathf.Clamp(mesh.bounds.center.y*.6f,.4f,.85f),0);var box=go.GetComponent<BoxCollider>();box.center=mesh.bounds.center;box.size=mesh.bounds.size;box.sharedMaterial=template.GetComponent<BoxCollider>().sharedMaterial;var movement=go.AddComponent<TestDriveMovement>();EditorUtility.CopySerialized(template,movement);Ref(movement,"resetPoint",null);Ref(movement,"followCamera",null);var parent=new GameObject("Wheel Colliders");parent.transform.SetParent(go.transform,false);var so=new SerializedObject(movement);var wheels=so.FindProperty("wheels");wheels.arraySize=4;var labels=new[]{"FL","FR","BL","BR"};
 for(int j=0;j<4;j++){var visual=go.GetComponentsInChildren<Transform>().Single(t=>t.name.EndsWith(" "+labels[j]+" Tire"));var wheelGO=new GameObject(labels[j]+" WheelCollider");wheelGO.transform.SetParent(parent.transform,false);wheelGO.transform.localPosition=visual.localPosition+Vector3.up*(templateWheel.suspensionDistance*.5f);var wheel=wheelGO.AddComponent<WheelCollider>();wheel.radius=visual.GetComponent<MeshFilter>().sharedMesh.bounds.extents.y;wheel.suspensionDistance=templateWheel.suspensionDistance;wheel.mass=templateWheel.mass;wheel.wheelDampingRate=templateWheel.wheelDampingRate;wheel.forceAppPointDistance=templateWheel.forceAppPointDistance;wheel.suspensionSpring=templateWheel.suspensionSpring;wheel.forwardFriction=templateWheel.forwardFriction;wheel.sidewaysFriction=templateWheel.sidewaysFriction;var element=wheels.GetArrayElementAtIndex(j);element.FindPropertyRelative("collider").objectReferenceValue=wheel;element.FindPropertyRelative("visual").objectReferenceValue=visual;element.FindPropertyRelative("steering").boolValue=j<2;element.FindPropertyRelative("driven").boolValue=j>=2;}
 so.ApplyModifiedPropertiesWithoutUndo();foreach(var probe in go.GetComponentsInChildren<ReflectionProbe>())probe.enabled=false;var saved=PrefabUtility.SaveAsPrefabAsset(go,dir+"/"+go.name+".prefab");catalog.drivingPrefabs[i]=saved.GetComponent<TestDriveMovement>();Object.DestroyImmediate(go);}
 AssetDatabase.CreateAsset(catalog,dir+"/VehicleCatalog.asset");Ref(manager,"testDriveCatalog",catalog);
 var buttons=showroom.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.UI.Button>(true)).ToArray();var back=buttons.Single(b=>b.name=="BackToTitleButton");var test=Object.Instantiate(back,back.transform.parent);test.name="TestDriveButton";var colors=test.colors;colors.normalColor=Color.white;colors.highlightedColor=new Color(1,1,.92f);colors.pressedColor=new Color(.8f,.8f,.8f);colors.selectedColor=Color.white;colors.disabledColor=new Color(.5f,.5f,.5f,.5f);test.colors=colors;foreach(var graphic in test.GetComponentsInChildren<UnityEngine.UI.Image>())if(graphic.name=="UpperStroke"||graphic.name=="LowerStroke")Object.DestroyImmediate(graphic.gameObject);Rect((RectTransform)test.transform,new Vector2(1,1),new Vector2(-64,-64),new Vector2(320,76));test.onClick=new UnityEngine.UI.Button.ButtonClickedEvent();UnityEventTools.AddPersistentListener(test.onClick,manager.TestDrive);test.GetComponent<UnityEngine.UI.Image>().color=new Color(.98f,.77f,.25f);test.GetComponentInChildren<TMP_Text>().text="TEST DRIVE";test.GetComponentInChildren<TMP_Text>().color=new Color(.04f,.05f,.065f);var ms=new SerializedObject(manager);var navigation=ms.FindProperty("navigationButtons");navigation.arraySize=buttons.Length+1;for(int i=0;i<buttons.Length;i++)navigation.GetArrayElementAtIndex(i).objectReferenceValue=buttons[i];navigation.GetArrayElementAtIndex(buttons.Length).objectReferenceValue=test;ms.ApplyModifiedPropertiesWithoutUndo();EditorSceneManager.MarkSceneDirty(showroom);EditorSceneManager.SaveScene(showroom);
 SceneManager.SetActiveScene(track);var follow=track.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<TestDriveCameraFollow>()).Single();var speed=track.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<TestDriveSpeedDisplay>()).Single();var map=track.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<TestDriveMinimap>()).Single();var spawn=track.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).Single(t=>t.name=="VehicleSpawn");var sessionGO=new GameObject("TestDriveSceneManager");var session=sessionGO.AddComponent<TestDriveSceneManager>();var audio=sessionGO.AddComponent<AudioSource>();audio.playOnAwake=false;audio.volume=.75f;Ref(session,"catalog",catalog);Ref(session,"spawnPoint",spawn);Ref(session,"followCamera",follow);Ref(session,"speedDisplay",speed);Ref(session,"minimap",map);Ref(session,"buttonAudio",audio);Ref(session,"returnSound",returnSound);Ref(follow,"target",null);Ref(speed,"vehicleBody",null);Ref(map,"vehicle",null);
 var hud=speed.GetComponent<Canvas>();if(!hud.GetComponent<UnityEngine.UI.GraphicRaycaster>())hud.gameObject.AddComponent<UnityEngine.UI.GraphicRaycaster>();var returnGO=new GameObject("BackToShowroomButton",typeof(RectTransform),typeof(UnityEngine.UI.Image),typeof(UnityEngine.UI.Button));returnGO.transform.SetParent(hud.transform,false);Rect((RectTransform)returnGO.transform,new Vector2(0,1),new Vector2(40,-40),new Vector2(320,68));returnGO.GetComponent<UnityEngine.UI.Image>().color=new Color(.035f,.045f,.06f,.94f);var returnButton=returnGO.GetComponent<UnityEngine.UI.Button>();var nav=returnButton.navigation;nav.mode=UnityEngine.UI.Navigation.Mode.None;returnButton.navigation=nav;UnityEventTools.AddPersistentListener(returnButton.onClick,session.ReturnToShowroom);Ref(session,"returnButton",returnButton);var labelGO=new GameObject("Label",typeof(RectTransform),typeof(TextMeshProUGUI));labelGO.transform.SetParent(returnGO.transform,false);var labelRect=(RectTransform)labelGO.transform;labelRect.anchorMin=Vector2.zero;labelRect.anchorMax=Vector2.one;labelRect.offsetMin=labelRect.offsetMax=Vector2.zero;var label=labelGO.GetComponent<TextMeshProUGUI>();label.font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/Fonts/Nunito/Nunito-Bold SDF.asset");label.fontSize=22;label.text="BACK TO SHOWROOM";label.color=new Color(.98f,.77f,.25f);label.alignment=TextAlignmentOptions.Center;label.raycastTarget=false;
 var eventGO=new GameObject("EventSystem",typeof(UnityEngine.EventSystems.EventSystem),typeof(UnityEngine.InputSystem.UI.InputSystemUIInputModule));eventGO.GetComponent<UnityEngine.InputSystem.UI.InputSystemUIInputModule>().AssignDefaultActions();Object.DestroyImmediate(template.gameObject);var build=EditorBuildSettings.scenes.ToList();if(!build.Any(s=>s.path==track.path))build.Add(new EditorBuildSettingsScene(track.path,true));else build.Single(s=>s.path==track.path).enabled=true;EditorBuildSettings.scenes=build.ToArray();EditorSceneManager.MarkSceneDirty(track);EditorSceneManager.SaveScene(track);AssetDatabase.SaveAssets();return "Created 9 driving variants; connected selected car, camera, speed display and minimap; added Test Drive and Back to Showroom buttons; enabled test track in build scenes.";
 }
